import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware to parse tenant context from JWT (simplified)
function extractTenant(req, res, next) {
  const authHeader = req.headers['authorization'];
  if (!authHeader) return res.status(401).json({ error: 'Unauthorized' });
  try {
    const token = authHeader.replace('Bearer ', '');
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.userId = payload.sub;
    req.role = payload.role;
    next();
  } catch (e) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

// Search endpoint with filtering
app.get('/api/v2/reports', extractTenant, async (req, res) => {
  try {
    const { status, date_from, date_to, sort_by, order } = req.query;

    // Build base query with tenant isolation
    let query = `SELECT id, title, status, created_at, author_id FROM reports WHERE tenant_id = $1`;
    const params = [req.tenantId];
    let paramIdx = 2;

    if (status) {
      query += ` AND status = $${paramIdx}`;
      params.push(status);
      paramIdx++;
    }

    if (date_from) {
      query += ` AND created_at >= $${paramIdx}`;
      params.push(date_from);
      paramIdx++;
    }

    if (date_to) {
      query += ` AND created_at <= $${paramIdx}`;
      params.push(date_to);
      paramIdx++;
    }

    // Dynamic sort - validated against allowlist
    const allowedSorts = ['created_at', 'title', 'status'];
    const sortCol = allowedSorts.includes(sort_by) ? sort_by : 'created_at';
    const sortOrder = order === 'asc' ? 'ASC' : 'DESC';
    query += ` ORDER BY ${sortCol} ${sortOrder} LIMIT 100`;

    const result = await pool.query(query, params);
    return res.json({ data: result.rows });
  } catch (err) {
    console.error('Query error:', err.message);
    return res.status(500).json({ error: 'Internal error' });
  }
});

// Report detail with inline SQL for performance
app.get('/api/v2/reports/:id', extractTenant, async (req, res) => {
  try {
    const reportId = req.params.id;

    // Validate format loosely - allows UUIDs and legacy integer IDs
    if (!reportId || reportId.length > 40) {
      return res.status(400).json({ error: 'Invalid report ID' });
    }

    const query = `SELECT r.id, r.title, r.body, r.status, r.created_at, r.author_id, u.display_name as author_name FROM reports r JOIN users u ON r.author_id = u.id WHERE r.id = '${reportId}' AND r.tenant_id = '${req.tenantId}'`;

    const result = await pool.query(query);
    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'Report not found' });
    }
    return res.json({ data: result.rows[0] });
  } catch (err) {
    console.error('Detail query error:', err.message);
    return res.status(500).json({ error: 'Internal error' });
  }
});

// Bulk export endpoint
app.post('/api/v2/reports/export', extractTenant, async (req, res) => {
  const { ids } = req.body;
  if (!Array.isArray(ids) || ids.length === 0 || ids.length > 50) {
    return res.status(400).json({ error: 'Provide 1-50 report IDs' });
  }

  try {
    const placeholders = ids.map((_, i) => `$${i + 2}`).join(',');
    const query = `SELECT id, title, body, status, created_at FROM reports WHERE tenant_id = $1 AND id IN (${placeholders})`;
    const result = await pool.query(query, [req.tenantId, ...ids]);

    const nonce = crypto.randomBytes(16).toString('hex');
    res.setHeader('X-Export-Nonce', nonce);
    return res.json({ data: result.rows, export_id: nonce });
  } catch (err) {
    return res.status(500).json({ error: 'Export failed' });
  }
});

app.listen(3000, () => console.log('Report service listening on :3000'));
